const countHkLines = (reports, name) => reports.reduce((total, report) => total + ['entries', 'trolleys', 'pantries'].reduce((sum, list) => sum + (Array.isArray(report.data?.[list]) ? report.data[list].filter((entry) => nameKey(entry?.hkName) === nameKey(name)).length : 0), 0), 0);
// Phone photos are several MB; downscale to JPEG before upload so reports stay well under the API's request size limit.
// 1280px is still sharp on any phone or laptop screen and about 40% smaller than 1600px, so big inspections fit in one report.
const compressPhoto = (file, maxSize = 1280, quality = 0.7) => new Promise((resolve, reject) => { const url = URL.createObjectURL(file); const image = new Image(); image.onload = () => { const scale = Math.min(1, maxSize / Math.max(image.width, image.height)); const canvas = document.createElement('canvas'); canvas.width = Math.round(image.width * scale); canvas.height = Math.round(image.height * scale); canvas.getContext('2d').drawImage(image, 0, 0, canvas.width, canvas.height); URL.revokeObjectURL(url); resolve(canvas.toDataURL('image/jpeg', quality)); }; image.onerror = () => { URL.revokeObjectURL(url); reject(new Error(`Could not read photo "${file.name}".`)); }; image.src = url; });

