function Login({ login, setLogin, signIn, message, notice, forgotPassword, emailReset, clearMessages }) { const [forgot, setForgot] = useState(false); const [forgotInfo, setForgotInfo] = useState(''); const [forgotError, setForgotError] = useState(''); const requestReset = async (event) => { event.preventDefault(); setForgotError(''); try { setForgotInfo(await forgotPassword(login.email)); } catch (error) { setForgotError(error.message); } }; if (forgot) return <div className="login"><section className="login-intro"><div className="property-mark" role="img" aria-label="HK SYNC" /><p className="kicker">OPERATIONS COMMAND CENTRE</p><h1>HK-SYNC</h1><p className="tagline">Housekeeping, perfectly synchronised</p></section><form className="login-form" onSubmit={requestReset}><div className="property-mark small" role="img" aria-label="HK SYNC" /><h2>Reset password</h2>{!emailReset ? <><p className="muted">Ask a manager to create a reset link for you. They'll send it to you, and it works for 24 hours.</p><p className="muted">Managers: open <b>People</b> and choose <b>Reset password</b> next to the person's name.</p></> : <><p className="muted">Enter your staff email and we'll send you a link to set a new password. No email? Ask a manager for a reset link.</p><label>Email<input type="email" value={login.email} onChange={(e) => setLogin({ ...login, email: e.target.value })} required /></label>{forgotError && <p className="error">{forgotError}</p>}{forgotInfo && <p className="success">{forgotInfo}</p>}<button className="primary">Send reset link <span>→</span></button></>}<button type="button" className="text" onClick={() => { setForgot(false); setForgotInfo(''); setForgotError(''); clearMessages(); }}>← Back to sign in</button></form></div>; return <div className="login"><section className="login-intro"><div className="property-mark" role="img" aria-label="HK SYNC" /><p className="kicker">OPERATIONS COMMAND CENTRE</p><h1>HK-SYNC</h1><p className="tagline">Housekeeping, perfectly synchronised</p></section><form className="login-form" onSubmit={signIn}><div className="property-mark small" role="img" aria-label="HK SYNC" /><h2>Welcome back</h2><p className="muted">Sign in with your staff account.</p><label>Email<input type="email" value={login.email} onChange={(e) => setLogin({ ...login, email: e.target.value })} /></label><label>Password<input type="password" value={login.password} onChange={(e) => setLogin({ ...login, password: e.target.value })} /></label>{notice && <p className="success">{notice}</p>}{message && <p className="error">{message}</p>}<button className="primary">Sign in <span>→</span></button><button type="button" className="text" onClick={() => { clearMessages(); setForgot(true); }}>Forgot password?</button>{import.meta.env.DEV && <small className="muted">Demo account: manager@bahari.local / password123</small>}</form></div>; }
// One housekeeper on the Overview performance lists; tapping opens their profile.
function PerformanceRow({ row, tone, openProfile }) {
  return <button type="button" className={`perf-row ${tone}`} onClick={() => openProfile(row.name)}><span className="perf-name"><b>{row.name}</b><small>{plural(row.rooms, 'room')}{tone === 'poor' && row.weakest ? ` · weakest: ${row.weakest.label} ${row.weakest.average}` : ''}</small></span><span className="perf-bar" aria-hidden="true"><i style={{ width: `${Math.min(100, row.average * 10)}%` }} /></span><strong>{row.average.toFixed(1)}</strong></button>;
}
// Overview "Supervisor points": each supervisor's Inspection Rate Program points toward the yearly target.
function SupervisorPointsPanel({ goals, setPage, openSupervisor }) {
  const { supervisor: target, deadline } = goals.targets;
  const rows = [...goals.supervisorPoints].sort((a, b) => b.points - a.points || a.name.localeCompare(b.name));
  return <section className="panel performance-panel"><div className="panel-title"><div><p className="kicker">SUPERVISOR POINTS · {goals.year}</p><h3>Progress to {target} points</h3><small className="muted">From Inspection Rate Program rooms (out of 50) · target by {deadlineLabel(deadline)}</small></div><button className="text" onClick={() => setPage('goals')}>View tracker →</button></div>
    <div className="perf-list sup-points">{rows.map((row) => <button type="button" key={row.id} className={`perf-row ${row.points >= target ? 'good' : 'goal'}`} onClick={() => openSupervisor(row.id, row.name)}><span className="perf-name"><b>{row.name}</b><small>{row.rooms ? `${plural(row.rooms, 'room')} · avg ${row.roomAverage}/50 · last ${row.lastInspected}` : 'Not inspected yet this year'}</small></span><span className="perf-bar" aria-hidden="true"><i style={{ width: `${Math.min(100, row.points / target * 100)}%` }} /></span><strong>{row.points}<small>/{target}</small></strong></button>)}{!rows.length && <Empty text="No active supervisors yet." />}</div></section>;
}
function PerformancePanel({ performance, openProfile, setPage }) {
  const { top, support, days, minRooms, goodAt, supportBelow, ranked, inspected } = performance;
  return <section className="panel performance-panel"><div className="panel-title"><div><p className="kicker">HOUSEKEEPER PERFORMANCE · LAST {days} DAYS</p><h3>Who is doing well, who needs support</h3><small className="muted">Average room score out of 10 · housekeepers with at least {minRooms} inspected rooms · {ranked} of {inspected} ranked</small></div><button className="text" onClick={() => setPage('people')}>All profiles →</button></div>
    <div className="perf-columns">
      <div className="perf-list"><h4 className="good">Performing well <small>{goodAt.toFixed(1)} and above</small></h4>{top.map((row) => <PerformanceRow key={row.name} row={row} tone="good" openProfile={openProfile} />)}{!top.length && <Empty text={`No one at ${goodAt.toFixed(1)} or above in the last ${days} days yet.`} />}</div>
      <div className="perf-list"><h4 className="poor">Need support <small>below {supportBelow.toFixed(1)}</small></h4>{support.map((row) => <PerformanceRow key={row.name} row={row} tone="poor" openProfile={openProfile} />)}{!support.length && <Empty text={`Nobody below ${supportBelow.toFixed(1)}. Well done, team.`} />}</div>
    </div></section>;
}
function Overview({ reports, tasks, goals, staff, openReport, chooseType, setPage, allowedTypes, isManager, performance, openProfile, openSupervisor, userId }) { /* Staff counts cover only what they filed: handovers handed to them appear in their lists but are not their work. */ const counted = isManager ? reports : reports.filter((item) => item.submittedBy === userId); const todayReports = counted.filter((item) => item.date === localToday()); const openTasks = tasks.filter((task) => task.status !== 'completed' && (isManager || task.assignedTo === userId)); const topTasks = [...openTasks].sort((a, b) => PRIORITY_ORDER[a.priority] - PRIORITY_ORDER[b.priority] || String(a.dueDate || '9').localeCompare(String(b.dueDate || '9'))).slice(0, 3); const hkRoster = goals ? goals.hkPoints.filter((row) => row.onRoster) : []; const flagged = todayReports.filter((item) => item.flagged).length; const countRooms = (list) => list.filter((item) => item.type !== 'guest_interaction').reduce((sum, item) => sum + (item.itemCount || 0), 0); const rooms = countRooms(todayReports);
  // Last 7 days, oldest first; index 6 is today and 5 is yesterday.
  const week = Array.from({ length: 7 }, (_, index) => counted.filter((item) => item.date === daysAgo(6 - index)));
  const trend = { reports: week.map((list) => list.length), rooms: week.map(countRooms), flagged: week.map((list) => list.filter((item) => item.flagged).length), active: week.map((list) => new Set(list.map((item) => item.submittedBy)).size) };
  const fieldStaff = staff.filter((person) => ['supervisor', 'driver', 'storekeeper'].includes(person.role) && person.active !== false).length; const recentPanel = <section className="panel"><div className="panel-title"><div><p className="kicker">RECENT ACTIVITY</p><h3>Latest reports</h3></div><button className="text" onClick={() => setPage('reports')}>View all →</button></div>{reports.filter((item) => item.type !== 'handover').slice(0, 5).map((item) => <ReportLine key={item.id} item={item} onOpen={openReport} />)}{!reports.some((item) => item.type !== 'handover') && <Empty text="No reports yet. Start today's first inspection." />}{reports.some((item) => item.type === 'handover') && <div className="handover-recent"><p className="kicker">SHIFT HANDOVERS</p>{reports.filter((item) => item.type === 'handover').slice(0, 3).map((item) => <ReportLine key={item.id} item={item} onOpen={openReport} />)}</div>}</section>; const quickPanel = <section className="panel quick"><p className="kicker">QUICK CAPTURE</p><h3>What are you logging?</h3>{allowedTypes.map((key) => <button onClick={() => chooseType(key)} key={key}><span>＋</span>{TYPES[key]}<b>→</b></button>)}</section>; const goalsPanel = goals && <section className="panel"><div className="panel-title"><div><p className="kicker">GOALS AT A GLANCE</p><h3>On track for this year</h3></div><button className="text" onClick={() => setPage('goals')}>View tracker →</button></div><div className="glance-stats"><div><strong>{goals.supervisorPoints.filter((row) => row.points >= goals.targets.supervisor).length} / {goals.supervisorPoints.length}</strong><small>supervisors at {goals.targets.supervisor} pts</small><Progress value={teamAverage(goals.supervisorPoints)} target={goals.targets.supervisor} /><small>avg {Math.round(teamAverage(goals.supervisorPoints))} pts each</small></div><div><strong>{hkRoster.filter((row) => row.points >= goals.targets.hk).length} / {hkRoster.length}</strong><small>HK staff at {goals.targets.hk} pts</small><Progress value={teamAverage(hkRoster)} target={goals.targets.hk} /><small>avg {Math.round(teamAverage(hkRoster))} pts each</small></div></div>{goals.smartGoals.map((goal) => <div className="glance-goal" key={goal.key}><span>{goal.label}</span>{goal.target ? <Progress value={goal.rate} target={goal.target} /> : <small className="muted">{goal.samples ? `Rate ${goal.rate}% · no target` : 'No scores yet'}</small>}</div>)}</section>; const tasksPanel = <section className="panel"><div className="panel-title"><div><p className="kicker">TASKS AT A GLANCE</p><h3>Open follow-ups</h3></div><button className="text" onClick={() => setPage('tasks')}>View all →</button></div><div className="glance-stats"><div><strong>{openTasks.length}</strong><small>open tasks</small></div><div><strong className={openTasks.some((task) => task.priority === 'urgent') ? 'red-text' : ''}>{openTasks.filter((task) => task.priority === 'urgent').length}</strong><small>urgent</small></div></div>{topTasks.map((task) => <TaskCard key={task.id} task={task} staff={staff} />)}{!openTasks.length && <Empty text="No open tasks." />}</section>; return <div className={`overview ${isManager ? 'dashboard' : ''}`}><div className="heading"><div><p className="kicker">TODAY AT A GLANCE</p><h2>Operations pulse</h2></div>{allowedTypes.length > 0 && <button className="primary" onClick={() => chooseType(allowedTypes[0])}>＋ New report</button>}</div><div className="stat-cards"><StatCard label="Reports submitted" value={todayReports.length} delta={trend.reports[6] - trend.reports[5]}><MiniBars values={trend.reports} tone="green" /></StatCard><StatCard label="Rooms inspected" value={rooms} delta={trend.rooms[6] - trend.rooms[5]}><MiniArea values={trend.rooms} /></StatCard><StatCard label="Needs attention" value={flagged} delta={trend.flagged[6] - trend.flagged[5]} better="down"><MiniBars values={trend.flagged} tone="red" /></StatCard>{isManager ? <StatCard label="Active staff" value={trend.active[6]} delta={trend.active[6] - trend.active[5]} note={`${trend.active[6]} of ${fieldStaff} staff today`}><MiniGauge value={trend.active[6]} max={fieldStaff} /></StatCard> : <StatCard label="My open tasks" value={openTasks.length} note={`${tasks.length - openTasks.length} of ${tasks.length} completed`}><MiniGauge value={tasks.length - openTasks.length} max={tasks.length} /></StatCard>}</div>{isManager ? <><div className="dash-top"><ScoreTrend reports={reports} />{quickPanel}</div><div className={`dash-bottom ${goalsPanel ? '' : 'two'}`}>{goalsPanel}{tasksPanel}{recentPanel}</div>{goals && <SupervisorPointsPanel goals={goals} setPage={setPage} openSupervisor={openSupervisor} />}{performance && <PerformancePanel performance={performance} openProfile={openProfile} setPage={setPage} />}</> : <div className="columns">{recentPanel}{quickPanel}</div>}</div>; }
// Manager Overview: the daily average score (out of 10) of each scored report type over the last 7 days.
// Shift Handover, Vehicle Checklist and Tools Control carry no scores, so they never appear. Colours follow the report type.
const TREND_TYPES = [['quality', 'Quality Checklist'], ['neglected', 'Neglected Area'], ['trolley_pantry', 'Trolley / Pantry'], ['guest_interaction', 'Guest Interaction'], ['inspection_rate', 'Inspection Rate Program']];
function ScoreTrend({ reports }) {
  const [hover, setHover] = useState(null);
  const days = Array.from({ length: 7 }, (_, index) => daysAgo(6 - index));
  const mean = (values) => (values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : null);
  const scored = reports.filter((report) => report.average > 0);
  const series = TREND_TYPES.map(([type, label], slot) => ({ type, label, slot: slot + 1, values: days.map((day) => mean(scored.filter((report) => report.type === type && report.date === day).map((report) => report.average))) }))
    .filter((line) => line.values.some((value) => value !== null));
  const todayAll = mean(scored.filter((report) => report.date === days[6]).map((report) => report.average));
  const W = 640; const H = 230; const left = 34; const right = 14; const top = 12; const bottom = 30;
  const x = (index) => left + index * ((W - left - right) / 6);
  const y = (value) => top + (1 - value / 10) * (H - top - bottom);
  // Lines break over days with no report of that type, so a gap never looks like a score.
  const paths = (values) => values.reduce((segments, value, index) => { if (value === null) { segments.push([]); return segments; } segments[segments.length - 1].push(`${x(index).toFixed(1)},${y(value).toFixed(1)}`); return segments; }, [[]]).filter((segment) => segment.length > 1);
  const dayLabel = (day) => new Date(`${day}T00:00:00`).toLocaleDateString([], { weekday: 'short', day: 'numeric' });
  const latest = (values) => [...values].reverse().find((value) => value !== null);
  return <section className="panel trend score-trend"><div className="panel-title"><div><p className="kicker">MANAGER PERFORMANCE VIEW</p><h3>Daily score by report type</h3><small className="muted">Average score out of 10 · last 7 days · every scored report, from supervisors and managers</small></div><strong className="trend-value">{todayAll === null ? '—' : todayAll.toFixed(1)}<small>/10 today</small></strong></div>
    {series.length ? <>
      <ul className="trend-legend">{series.map((line) => <li key={line.type}><i className={`series-${line.slot}`} aria-hidden="true" /><span>{line.label}</span><b>{latest(line.values).toFixed(1)}</b></li>)}</ul>
      <div className="trend-plot" onMouseLeave={() => setHover(null)}>
        <svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label={`Daily score by report type, last 7 days: ${series.map((line) => `${line.label} latest ${latest(line.values).toFixed(1)}`).join('; ')}`}>
          {[0, 2, 4, 6, 8, 10].map((tick) => <g key={tick}><line className="trend-grid" x1={left} x2={W - right} y1={y(tick)} y2={y(tick)} /><text className="trend-axis" x={left - 8} y={y(tick) + 4} textAnchor="end">{tick}</text></g>)}
          {days.map((day, index) => <text key={day} className={`trend-axis ${hover === index ? 'on' : ''}`} x={x(index)} y={H - 8} textAnchor="middle">{dayLabel(day)}</text>)}
          {hover !== null && <line className="trend-cross" x1={x(hover)} x2={x(hover)} y1={top} y2={H - bottom} />}
          {series.map((line) => <g key={line.type} className={`series-${line.slot}`}>{paths(line.values).map((points, index) => <polyline key={index} className="trend-line" points={points.join(' ')} />)}{line.values.map((value, index) => value !== null && <circle key={index} className="trend-dot" cx={x(index)} cy={y(value)} r={hover === index ? 5.5 : 4} />)}</g>)}
          {days.map((day, index) => <rect key={day} className="trend-hit" x={x(index) - (W - left - right) / 12} y={top} width={(W - left - right) / 6} height={H - top - bottom} onMouseEnter={() => setHover(index)} onClick={() => setHover(index)} />)}
        </svg>
        {hover !== null && <div className={`trend-tip ${hover > 3 ? 'flip' : ''}`} style={{ left: `${(x(hover) / W) * 100}%` }}><b>{dayLabel(days[hover])}</b>{series.map((line) => <span key={line.type}><i className={`series-${line.slot}`} aria-hidden="true" />{line.label}<b>{line.values[hover] === null ? '—' : line.values[hover].toFixed(1)}</b></span>)}</div>}
      </div>
    </> : <Empty text="Scores will appear after inspection reports are submitted." />}
  </section>;
}
// Overview stat cards: a figure, its change since yesterday, and a small chart of the last 7 days.
// `better` says which direction is good news ('up', or 'down' for problems such as flagged reports).
function StatCard({ label, value, delta, better = 'up', note, children }) {
  const change = delta === undefined ? null : delta === 0 ? 'same' : (delta > 0) === (better === 'up') ? 'good' : 'bad';
  return <div className="stat-card"><h3>{label}</h3><div className="stat-body"><div className="stat-value">{value}{change && change !== 'same' && <svg className={`stat-arrow ${change}`} viewBox="0 0 12 14" aria-hidden="true"><path d={delta > 0 ? 'M6 1 11 7H8v6H4V7H1z' : 'M6 13 1 7h3V1h4v6h3z'} /></svg>}</div><small className="stat-note">{note ?? (delta === 0 ? 'Same as yesterday' : `${delta > 0 ? '+' : ''}${delta} from yesterday`)}</small><div className="stat-chart">{children}</div></div></div>;
}
function MiniBars({ values, tone }) {
  const id = useId();
  const max = Math.max(1, ...values);
  return <svg viewBox="0 0 84 44" role="img" aria-label={`Last 7 days: ${values.join(', ')}`}><defs><pattern id={id} width="5" height="5" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="5" height="5" className={`bar-fill ${tone}`} /><rect width="2" height="5" className="bar-stripe" /></pattern></defs>{values.map((value, index) => { const height = Math.max(3, (value / max) * 42); const last = index === values.length - 1; return <rect key={index} x={index * 12} y={44 - height} width="8" height={height} rx="2" className={last ? '' : 'bar-rest'} fill={last ? `url(#${id})` : undefined} />; })}</svg>;
}
function MiniArea({ values }) {
  const id = useId();
  const max = Math.max(1, ...values);
  const points = values.map((value, index) => [2 + index * (80 / (values.length - 1)), 40 - (value / max) * 34]);
  const line = points.map(([x, y], index) => `${index ? 'L' : 'M'}${x.toFixed(1)} ${y.toFixed(1)}`).join(' ');
  const [endX, endY] = points.at(-1);
  return <svg viewBox="0 0 84 44" role="img" aria-label={`Last 7 days: ${values.join(', ')}`}><defs><linearGradient id={id} x1="0" y1="0" x2="0" y2="1"><stop offset="0" className="area-top" /><stop offset="1" className="area-bottom" /></linearGradient></defs><path d={`${line} L${endX.toFixed(1)} 44 L2 44 Z`} fill={`url(#${id})`} /><path d={line} className="area-line" /><circle cx={endX} cy={endY} r="3.2" className="area-dot" /></svg>;
}
function MiniGauge({ value, max }) {
  const share = max ? Math.min(1, value / max) : 0;
  const angle = Math.PI * (1 - share);
  const end = [42 + 34 * Math.cos(angle), 42 - 34 * Math.sin(angle)];
  return <svg viewBox="0 0 84 48" role="img" aria-label={`${value} of ${max}`}><path d="M8 42 A34 34 0 0 1 76 42" className="gauge-track" />{share > 0 && <path d={`M8 42 A34 34 0 0 1 ${end[0].toFixed(1)} ${end[1].toFixed(1)}`} className="gauge-fill" />}{share > 0 && <circle cx={end[0]} cy={end[1]} r="4.5" className="gauge-knob" />}</svg>;
}
// The housekeepers a report is about, for the Latest reports list ("Amina Said, Pili Omar +2").
const HK_REPORT_TYPES = ['quality', 'neglected', 'trolley_pantry', 'guest_interaction'];
const reportHousekeepers = (item) => { if (!HK_REPORT_TYPES.includes(item.type)) return ''; const lines = [...(item.data?.entries || []), ...(item.data?.trolleys || []), ...(item.data?.pantries || [])]; const names = [...new Set(lines.map((line) => String(line?.hkName || '').trim()).filter(Boolean))]; return names.length > 2 ? `${names.slice(0, 2).join(', ')} +${names.length - 2}` : names.join(', '); };
function ReportLine({ item, onOpen }) { const housekeepers = reportHousekeepers(item); return <button type="button" className="report-line" onClick={() => onOpen?.(item.id)}><div className={`status-icon ${item.flagged ? 'bad' : ''}`}>{item.flagged ? '!' : '✓'}</div><div><strong>{TYPES[item.type]}</strong><small>{item.type === 'handover' ? `${item.data?.handoverFrom || item.submitter?.name} → ${item.data?.receivedBy || '—'}` : item.submitter?.name} · {item.date}</small>{housekeepers && <small className="report-line-hk">HK: {housekeepers}</small>}{item.type === 'inspection_rate' && item.data?.supervisorName && <small className="report-line-hk">Supervisor: {item.data.supervisorName}</small>}</div><span className={`badge ${item.flagged ? 'danger' : 'good'}`}>{item.flagged ? 'Needs attention' : 'Clear'}</span></button>; }
function Reports({ reports, tabCounts, me, staff, openReport, ask, openDiscussion, filters, setFilters, isManager, setTaskDraft, sign, exportExcel, exportPdf }) { const handovers = filters.tab === 'handovers'; return <><div className="heading"><div><p className="kicker">{isManager ? 'MANAGER REVIEW' : handovers ? 'ALL SUPERVISORS' : 'MY REPORTS'}</p><h2>{handovers ? 'Shift handovers' : 'Report register'}</h2></div><div><button className="secondary" onClick={exportPdf}>↓ PDF</button><button className="primary" onClick={exportExcel}>↓ Excel</button></div></div><div className="segmented report-tabs" role="tablist" aria-label="Report kind">{[['reports', 'Inspections & checklists'], ['handovers', 'Shift handovers']].map(([key, label]) => <button type="button" role="tab" key={key} className={filters.tab === key ? 'active' : ''} aria-selected={filters.tab === key} onClick={() => setFilters({ ...filters, tab: key, type: '' })}>{label} <span className="tab-count">{tabCounts[key]}</span></button>)}</div><div className="filters"><input placeholder={handovers ? 'Search by who handed over or received' : 'Search staff or report type'} value={filters.search} onChange={(e) => setFilters({ ...filters, search: e.target.value })} />{!handovers && <select value={filters.type} onChange={(e) => setFilters({ ...filters, type: e.target.value })}><option value="">All report types</option>{(isManager ? Object.keys(TYPES) : typesForRole(me?.role)).filter((key) => key !== 'handover').map((key) => <option value={key} key={key}>{TYPES[key]}</option>)}</select>}<input type="date" value={filters.date} onChange={(e) => setFilters({ ...filters, date: e.target.value })} /></div><div className="table scroll dense"><div className="table-head"><span>Report</span><span>Submitted by</span><span>Date</span><span>Result</span><span /></div>{reports.map((item) => <div className="table-row" key={item.id}><div><button type="button" className="name-link" onClick={() => openReport(item.id)}>{TYPES[item.type]}</button><DiscussionChip discussion={item.discussion} open={openDiscussion} />{item.itemCount > 0 && <small>{item.itemCount} line {item.itemCount === 1 ? 'item' : 'items'}</small>}{item.type === 'inspection_rate' && item.data?.supervisorName && <small>SPV: {item.data.supervisorName}</small>}{item.type === 'handover' && <small>To: {item.data?.receivedBy || '—'}{item.data?.needsManager ? ` · Needs a manager${item.data.managerTopic ? `: ${item.data.managerTopic}` : ''}` : ''}</small>}</div><span>{item.submitter?.name}</span><span>{item.date}</span><span className={`badge ${item.flagged ? 'danger' : 'good'}`}>{item.flagged ? 'Needs attention' : 'Clear'}</span><div className="row-actions">{item.flagged && isManager && <button onClick={() => setTaskDraft({ title: `${TYPES[item.type]} follow-up`, location: item.data?.area || item.data?.block || 'Resort', priority: 'urgent', dueDate: localToday() })}>＋ Task</button>}{isManager && !item.hodSignedAt && <button onClick={() => sign(item.id)}>Sign off</button>}<button onClick={() => ask(reportAsk(item, me, staff))} title="Ask about this report">💬 Ask</button></div></div>)}{!reports.length && <Empty text={handovers ? 'No shift handovers match these filters.' : 'No reports match these filters.'} />}</div></>; }
const TASK_ACTIONS = { pending: [['in_progress', 'Start']], in_progress: [['completed', 'Complete'], ['pending', 'Back to pending']], completed: [['in_progress', 'Reopen']] };
const PRIORITY_ORDER = { urgent: 0, medium: 1, low: 2 };
function TaskCard({ task, staff, userId, children }) { return <article className={`task ${userId && task.assignedTo === userId ? 'task-mine' : ''}`}><b className={`priority ${task.priority}`}>{task.priority}</b><h4>{task.title}</h4><p>⌖ {task.location}</p><small>Due {task.dueDate || '—'} · {task.assignedTo && task.assignedTo === userId ? 'You' : staff.find((person) => person.id === task.assignedTo)?.name || 'Unassigned'}</small>{children}</article>; }
function Tasks({ tasks, staff, isManager, userId, role, setTaskDraft, updateStatus, ask, openDiscussion, remove }) { /* Supervisors see every supervisor's tasks and can update them when covering for a colleague. */ const assigneeRole = (task) => staff.find((person) => person.id === task.assignedTo)?.role; const canUpdate = (task) => isManager || task.assignedTo === userId || (role === 'supervisor' && assigneeRole(task) === 'supervisor'); const [onlyMine, setOnlyMine] = useState(false); const shown = onlyMine ? tasks.filter((task) => task.assignedTo === userId) : tasks; return <><div className="heading"><div><p className="kicker">FOLLOW-UP WORK</p><h2>Task board</h2></div>{role === 'supervisor' && <div className="task-scope" role="group" aria-label="Which tasks"><button type="button" className={onlyMine ? '' : 'active'} aria-pressed={!onlyMine} onClick={() => setOnlyMine(false)}>All supervisors</button><button type="button" className={onlyMine ? 'active' : ''} aria-pressed={onlyMine} onClick={() => setOnlyMine(true)}>Only mine</button></div>}{isManager && <button className="primary" onClick={() => setTaskDraft({ title: '', location: '', priority: 'medium', dueDate: localToday() })}>＋ New task</button>}</div><div className="task-columns">{['pending', 'in_progress', 'completed'].map((status) => <section className="task-column" key={status}><div className="column-title"><h3>{status === 'in_progress' ? 'In progress' : status[0].toUpperCase() + status.slice(1)}</h3><span>{shown.filter((task) => task.status === status).length}</span></div>{shown.filter((task) => task.status === status).map((task) => <TaskCard key={task.id} task={task} staff={staff} userId={userId}><div className="row-actions task-actions">{canUpdate(task) && TASK_ACTIONS[task.status]?.map(([next, label]) => <button key={next} onClick={() => updateStatus(task.id, next)}>{label}</button>)}<button onClick={() => ask(taskAsk(task, userId, staff))} title="Ask about this task">💬 Ask</button><DiscussionChip discussion={task.discussion} open={openDiscussion} />{isManager && <button type="button" className="danger" onClick={() => remove(task)} aria-label={`Delete task ${task.title}`}>Delete</button>}</div></TaskCard>)}</section>)}</div></>; }
function ProfileList({ request, openProfile }) { const [period, setPeriod] = useState('year'); const [rows, setRows] = useState(null); useEffect(() => { let live = true; setRows(null); request(`/hk-profiles?period=${period}`).then((result) => live && setRows(result.profiles || [])).catch(() => live && setRows([])); return () => { live = false; }; }, [period]); return <><div className="heading"><div><p className="kicker">COACHING VIEW</p><h2>Housekeeper profiles</h2><p className="muted">Strengths and weaknesses from every inspection. Click a name to open their profile.</p></div><PeriodSwitch period={period} setPeriod={setPeriod} /></div><div className="panel table performance scroll dense profile-list"><div className="table-head"><span>Housekeeper</span><span>Rooms</span><span>Average</span><span>Top strength</span><span>Needs work</span><span>Last inspected</span></div>{rows === null ? <Empty text="Loading profiles…" /> : [...rows].sort((a, b) => b.rooms - a.rooms || a.name.localeCompare(b.name)).map((row) => <button type="button" className="table-row profile-row" key={row.name} onClick={() => openProfile(row.name)}><strong>{row.name}</strong><span><small className="cell-label">Rooms</small>{row.rooms || '—'}</span><span><small className="cell-label">Average</small>{row.average ?? '—'}</span><span className="green-text"><small className="cell-label">Top strength</small>{row.strength ? `${row.strength.label} · ${row.strength.average}` : '—'}</span><span className="red-text"><small className="cell-label">Needs work</small>{row.weakness ? `${row.weakness.label} · ${row.weakness.average}` : '—'}</span><span><small className="cell-label">Last inspected</small>{row.lastInspected || '—'}</span></button>)}{rows && !rows.length && <Empty text="Add housekeepers to the roster on the Goals page." />}</div></>; }
function SupervisorProfileList({ request, openSupervisor }) { const [period, setPeriod] = useState('year'); const [data, setData] = useState(null); useEffect(() => { let live = true; setData(null); request(`/supervisor-profiles?period=${period}`).then((result) => live && setData(result)).catch(() => live && setData({ profiles: [] })); return () => { live = false; }; }, [period]); const rows = data?.profiles; return <><div className="heading"><div><p className="kicker">SUPERVISOR VIEW</p><h2>Supervisor profiles</h2><p className="muted">How managers rate each supervisor in the Inspection Rate Program, plus their own reports and tasks. Click a name to open their profile.</p></div><PeriodSwitch period={period} setPeriod={setPeriod} /></div><div className="panel table performance scroll dense profile-list"><div className="table-head"><span>Supervisor</span><span>Points</span><span>Room average</span><span>Top strength</span><span>Needs work</span><span>Last inspected</span></div>{rows === undefined ? <Empty text="Loading profiles…" /> : [...rows].sort((a, b) => b.points - a.points || a.name.localeCompare(b.name)).map((row) => <button type="button" className="table-row profile-row" key={row.id} onClick={() => openSupervisor(row.id, row.name)}><strong>{row.name}</strong><span><small className="cell-label">Points</small>{row.points}/{data.target}</span><span><small className="cell-label">Room average</small>{row.roomAverage === null ? '—' : `${row.roomAverage}/50`}</span><span className="green-text"><small className="cell-label">Top strength</small>{row.strength ? `${row.strength.label} · ${row.strength.average}` : '—'}</span><span className="red-text"><small className="cell-label">Needs work</small>{row.weakness ? `${row.weakness.label} · ${row.weakness.average}` : '—'}</span><span><small className="cell-label">Last inspected</small>{row.lastInspected || '—'}</span></button>)}{rows && !rows.length && <Empty text="No active supervisors yet. Add them under Staff accounts." />}</div></>; }
function SupervisorProfile({ id, name, request, back, openReport }) { const [period, setPeriod] = useState('year'); const [data, setData] = useState(null); const [error, setError] = useState(''); useEffect(() => { let live = true; setData(null); setError(''); request(`/supervisor-profiles/${encodeURIComponent(id)}?period=${period}`).then((result) => live && setData(result)).catch((failure) => live && setError(failure.message)); return () => { live = false; }; }, [id, period]); const header = <div className="heading"><div><button type="button" className="text back-link" onClick={back}>← Back</button><p className="kicker">SUPERVISOR PROFILE{data && !data.profile.active ? ' · DEACTIVATED' : ''}</p><h2>{data?.profile.name || name}</h2></div><PeriodSwitch period={period} setPeriod={setPeriod} /></div>; if (error) return <>{header}<Empty text={error} /></>; if (!data) return <>{header}<Empty text="Loading profile…" /></>; const { profile, rules } = data; const { work, tasks } = profile; const judged = (item) => item.count >= rules.minScores; const tone = (item) => !judged(item) ? '' : item.average >= rules.strengthAt ? 'strong' : item.average < rules.weaknessBelow ? 'weak' : ''; const card = (item) => <li key={item.label}><span>{item.label}</span><b>{item.average}</b><small className="muted">team {item.team ?? '—'} · {plural(item.count, 'score')}</small></li>; const periodLabel = period === 'year' ? 'This financial year' : 'All time'; return <div className="profile">{header}<div className="metrics"><div className="metric gold"><span>Supervisor points</span><strong>{profile.points.points}</strong><small>of {profile.points.target} by {deadlineLabel(profile.points.deadline)}</small></div><div className="metric"><span>Rooms rated by managers</span><strong>{profile.rooms}</strong><small>{profile.flagged ? `${profile.flagged} under 40/50` : periodLabel}</small></div><div className="metric green"><span>Room average</span><strong>{profile.roomAverage ?? '—'}</strong><small>Out of 50</small></div><div className="metric"><span>Last inspected</span><strong className="metric-date">{profile.lastInspected ? deadlineLabel(profile.lastInspected) : '—'}</strong><small>&nbsp;</small></div></div><div className="profile-cards"><section className="panel strengths"><p className="kicker">STRENGTHS</p><h3>Doing well</h3>{profile.strengths.length ? <ul className="item-cards">{profile.strengths.map(card)}</ul> : <p className="muted">None yet. An item becomes a strength at an average of {rules.strengthAt}+ over {rules.minScores} or more scores.</p>}</section><section className="panel weaknesses"><p className="kicker">NEEDS WORK</p><h3>Coach on these</h3>{profile.weaknesses.length ? <ul className="item-cards">{profile.weaknesses.map(card)}</ul> : <p className="muted">Nothing below {rules.weaknessBelow} yet (items need {rules.minScores}+ scores to be judged).</p>}</section></div><section className="panel profile-items"><div className="panel-title"><div><p className="kicker">INSPECTION RATE PROGRAM</p><h3>Each item vs all supervisors</h3><small className="muted">Average score out of 10 from managers' inspections</small></div></div>{profile.items.map((item) => <div className={`item-row ${tone(item)}`} key={item.label}><span>{item.label}</span><Progress value={item.average} target={10} /><b>{item.average}</b><small className="muted">team {item.team ?? '—'} · {item.count}×</small></div>)}{!profile.items.length && <Empty text="No Inspection Rate Program rooms in this period." />}</section><div className="columns profile-lower"><section className="panel"><p className="kicker">TREND</p><h3>Average item score by month</h3>{profile.trend.length ? <div className="chart"><div className="chart-axis"><span>10</span><span>8</span><span>6</span><span>4</span><span>2</span><span>0</span></div><div className="chart-area">{profile.trend.map((point) => <div className="chart-column" key={point.month}><div className="chart-bar" style={{ height: `${Math.max(8, point.average * 10)}%` }} title={`${monthLabel(point.month)}: ${point.average}/10 over ${plural(point.rooms, 'room')}`}><b>{point.average}</b></div><small>{monthLabel(point.month)}</small></div>)}</div></div> : <Empty text="No inspections in this period." />}</section><section className="panel"><p className="kicker">LATEST INSPECTIONS</p><h3>Rooms managers rated</h3>{profile.recent.length ? profile.recent.map((room, index) => <div className="flag-line" key={index}><div><button type="button" className="name-link" onClick={() => openReport(room.reportId)}>{room.room ? `Room ${room.room}` : room.area || 'Inspection'}</button><small className="muted">{deadlineLabel(room.date)} · by {room.inspectedBy}</small>{room.remarks && <p>“{room.remarks}”</p>}</div><span className={`badge ${room.average < 8 ? 'danger' : 'good'}`}>{room.total}/{room.outOf}</span></div>) : <p className="muted">No Inspection Rate Program rooms in this period.</p>}</section></div><div className="columns profile-lower"><section className="panel"><p className="kicker">THEIR OWN WORK</p><h3>Reports they filed</h3><div className="progress-tiles"><div><span>Reports filed</span><b>{work.reports}</b></div><div><span>Rooms scored</span><b>{work.roomsScored}</b></div><div><span>Housekeepers</span><b>{work.housekeepers}</b></div><div><span>Score they give</span><b>{work.averageGiven ?? '–'}</b><small>all supervisors {work.teamAverageGiven ?? '–'}</small></div></div>{work.byType.length > 0 && <ul className="type-counts">{work.byType.map((row) => <li key={row.type}><span>{row.label}</span><b>{row.count}</b></li>)}</ul>}<small className="muted">{work.lastReport ? `Last report ${deadlineLabel(work.lastReport)}` : 'No reports in this period.'}</small></section><section className="panel"><p className="kicker">TASKS</p><h3>Follow-ups sent to them</h3><div className="progress-tiles"><div><span>Open</span><b>{tasks.open}</b></div><div><span>Overdue</span><b className={tasks.overdue ? 'red-text' : ''}>{tasks.overdue}</b></div><div><span>Completed</span><b>{tasks.completed}</b></div><div><span>Done on time</span><b>{tasks.withDueDate ? `${tasks.onTime}/${tasks.withDueDate}` : '–'}</b></div></div></section></div></div>; }
function PeriodSwitch({ period, setPeriod }) { return <div className="segmented" role="group" aria-label="Period">{[['year', 'This financial year'], ['all', 'All time']].map(([key, label]) => <button type="button" key={key} className={period === key ? 'active' : ''} aria-pressed={period === key} onClick={() => setPeriod(key)}>{label}</button>)}</div>; }
const monthLabel = (month) => new Date(`${month}-01T00:00:00`).toLocaleDateString([], { month: 'short', year: '2-digit' });
function HkProfile({ name, request, back, openReport }) { const [period, setPeriod] = useState('year'); const [data, setData] = useState(null); const [error, setError] = useState(''); useEffect(() => { let live = true; setData(null); setError(''); request(`/hk-profiles/${encodeURIComponent(name)}?period=${period}`).then((result) => live && setData(result)).catch((failure) => live && setError(failure.message)); return () => { live = false; }; }, [name, period]); const header = <div className="heading"><div><button type="button" className="text back-link" onClick={back}>← Back</button><p className="kicker">HOUSEKEEPER PROFILE{data && !data.profile.onRoster ? ' · NOT ON ROSTER' : ''}</p><h2>{name}</h2></div><PeriodSwitch period={period} setPeriod={setPeriod} /></div>; if (error) return <>{header}<Empty text={error} /></>; if (!data) return <>{header}<Empty text="Loading profile…" /></>; const { profile, rules } = data; const judged = (item) => item.count >= rules.minScores; const tone = (item) => !judged(item) ? '' : item.average >= rules.strengthAt ? 'strong' : item.average < rules.weaknessBelow ? 'weak' : ''; const card = (item) => <li key={item.label}><span>{item.label}</span><b>{item.average}</b><small className="muted">team {item.team ?? '—'} · {plural(item.count, 'score')}</small></li>; return <div className="profile">{header}<div className="metrics"><div className="metric"><span>Rooms inspected</span><strong>{profile.rooms}</strong><small>{period === 'year' ? 'This financial year' : 'All time'}</small></div><div className="metric green"><span>Average score</span><strong>{profile.average ?? '—'}</strong><small>Out of 10</small></div><div className="metric gold"><span>HK points</span><strong>{profile.points.points}</strong><small>of {profile.points.target} by {deadlineLabel(profile.points.deadline)}</small></div><div className="metric"><span>Last inspected</span><strong className="metric-date">{profile.lastInspected ? deadlineLabel(profile.lastInspected) : '—'}</strong><small>&nbsp;</small></div></div><div className="profile-cards"><section className="panel strengths"><p className="kicker">STRENGTHS</p><h3>Doing well</h3>{profile.strengths.length ? <ul className="item-cards">{profile.strengths.map(card)}</ul> : <p className="muted">None yet. An item becomes a strength at an average of {rules.strengthAt}+ over {rules.minScores} or more scores.</p>}</section><section className="panel weaknesses"><p className="kicker">NEEDS WORK</p><h3>Coach on these</h3>{profile.weaknesses.length ? <ul className="item-cards">{profile.weaknesses.map(card)}</ul> : <p className="muted">Nothing below {rules.weaknessBelow} yet (items need {rules.minScores}+ scores to be judged).</p>}</section></div><section className="panel profile-items"><div className="panel-title"><div><p className="kicker">EVERY ITEM</p><h3>Their average vs the team</h3></div></div>{PROFILE_GROUPS.filter((group) => profile.items.some((item) => item.group === group)).map((group) => <div className="item-group" key={group}><p className="kicker">{group}</p>{profile.items.filter((item) => item.group === group).map((item) => <div className={`item-row ${tone(item)}`} key={item.label}><span>{item.label}</span><Progress value={item.average} target={10} /><b>{item.average}</b><small className="muted">team {item.team ?? '—'} · {item.count}×</small></div>)}</div>)}{!profile.items.length && <Empty text="No scored inspections in this period." />}</section><div className="columns profile-lower"><section className="panel"><p className="kicker">TREND</p><h3>Average room score by month</h3>{profile.trend.length ? <div className="chart"><div className="chart-axis"><span>10</span><span>8</span><span>6</span><span>4</span><span>2</span><span>0</span></div><div className="chart-area">{profile.trend.map((point) => <div className="chart-column" key={point.month}><div className="chart-bar" style={{ height: `${Math.max(8, point.average * 10)}%` }} title={`${monthLabel(point.month)}: ${point.average}/10 over ${plural(point.rooms, 'room')}`}><b>{point.average}</b></div><small>{monthLabel(point.month)}</small></div>)}</div></div> : <Empty text="No inspections in this period." />}</section><section className="panel"><p className="kicker">GUEST INTERACTION</p><h3>Latest checks</h3>{profile.checks.length ? profile.checks.map((check, index) => <div className="check-line" key={index}><small className="muted">{deadlineLabel(check.date)}</small><div className="check-scores">{INTERACTION.map(([item]) => <span key={item}>{item} <b>{check.scores[item] ?? '–'}</b></span>)}</div>{check.note && <p>{check.note}</p>}</div>) : <p className="muted">No Guest Interaction Checks yet.</p>}</section></div><div className="columns profile-lower"><section className="panel"><p className="kicker">FLAGGED ROOMS</p><h3>Needed attention</h3>{profile.flagged.length ? profile.flagged.map((room, index) => <div className="flag-line" key={index}><div><button type="button" className="name-link" onClick={() => openReport(room.reportId)}>{room.place || room.type}</button><small className="muted">{deadlineLabel(room.date)} · {room.type}</small>{room.remarks && <p>“{room.remarks}”</p>}</div><span className={`badge ${room.average < 6 ? 'danger' : 'good'}`}>{room.average}/10</span></div>) : <p className="muted">No flagged rooms in this period.</p>}</section><section className="panel"><p className="kicker">GOALS PROGRESS</p><h3>This financial year</h3>{profile.progress ? <div className="progress-tiles">{HK_AREAS.map(([key, label]) => { const [toneClass, text] = scoreTag(profile.progress[key]); return <div key={key}><span>{label}</span><b>{profile.progress[key] ?? '–'}</b><b className={`tag ${toneClass}`}>{text}</b></div>; })}</div> : <p className="muted">Not on the Goals roster, so no goals progress.</p>}</section></div></div>; }
// The file input stays uncontrolled (saveReport reads every photo input when the form is sent); this only shows what was picked.
// One file input per picker (saveReport reads them in order); "capture" decides whether the phone opens the camera or the gallery.
function PhotoPicker({ existing = null } = {}) { const input = useRef(null); const [preview, setPreview] = useState(null); useEffect(() => () => { if (preview) URL.revokeObjectURL(preview); }, [preview]); const clear = () => { if (input.current) input.current.value = ''; setPreview(null); }; const pick = (camera) => { const el = input.current; if (!el) return; if (camera) el.setAttribute('capture', 'environment'); else el.removeAttribute('capture'); el.click(); }; return <span className={`photo-picker ${preview || existing ? 'has-photo' : ''}`}><input ref={input} type="file" accept="image/*" hidden onChange={(e) => { const file = e.target.files?.[0]; setPreview(file ? URL.createObjectURL(file) : null); }} />{!preview && existing ? <button type="button" className="photo" onClick={() => pick(false)}><img src={existing} alt="Saved photo" /><span>Saved photo · change</span></button> : preview ? <button type="button" className="photo" onClick={() => pick(false)}><img src={preview} alt="Chosen photo" /><span>Photo added · change</span></button> : <><button type="button" className="photo" onClick={() => pick(true)} aria-label="Take a photo">📷 Camera</button><button type="button" className="photo" onClick={() => pick(false)} aria-label="Choose a photo">＋ Photo</button></>}{preview && <button type="button" className="photo-remove" onClick={clear} aria-label="Remove photo" title="Remove photo">×</button>}</span>; }
// Who can take over a shift: active supervisors first, then managers; never yourself.
const handoverPeople = (staff, me) => staff.filter((person) => person.active !== false && person.id !== me?.id && ['supervisor', 'assistant_manager', 'manager'].includes(person.role)).sort((a, b) => (a.role === 'supervisor' ? 0 : 1) - (b.role === 'supervisor' ? 0 : 1) || a.name.localeCompare(b.name));
// HK name: pick from the housekeeping roster, so a typo can never send scores to nobody. Phones show this as a scrolling list.
// A name already on a report but no longer on the roster stays selectable when editing. If the roster has not loaded, typing still works.
function HkSelect({ roster, value, onChange, required = false }) {
  const names = [...roster].sort((a, b) => a.localeCompare(b));
  if (!names.length) return <input value={value || ''} onChange={(e) => onChange(e.target.value)} required={required} placeholder="Housekeeper's name" />;
  const offRoster = value && !names.some((name) => name.toLowerCase() === String(value).trim().toLowerCase());
  return <select className="hk-select" value={value || ''} onChange={(e) => onChange(e.target.value)} required={required}><option value="">Choose housekeeper</option>{offRoster && <option value={value}>{value} (not on roster)</option>}{names.map((name) => <option key={name} value={name}>{name}</option>)}</select>;
}
